.stick-zone { position: absolute; left: max(20px, env(safe-area-inset-left)); bottom: max(90px, calc(env(safe-area-inset-bottom) + 74px)); width: 120px; height: 120px; pointer-events: auto; touch-action: none; }
.stick-base { position: absolute; inset: 0; border-radius: 50%; border: 1px solid rgba(239,228,205,.22); background: radial-gradient(circle, rgba(255,255,255,.05), rgba(0,0,0,.25)); }
.stick-base::before, .stick-base::after { content: ""; position: absolute; background: rgba(239,228,205,.12); }
.stick-base::before { left: 50%; top: 12%; bottom: 12%; width: 1px; }
.stick-base::after { top: 50%; left: 12%; right: 12%; height: 1px; }
.stick-knob { position: absolute; left: 50%; top: 50%; width: 48px; height: 48px; margin: -24px 0 0 -24px; border-radius: 50%; background: rgba(239,228,205,.18); border: 1px solid rgba(239,228,205,.4); box-shadow: 0 4px 12px rgba(0,0,0,.4); }
.mob-buttons { position: absolute; right: max(18px, env(safe-area-inset-right)); bottom: max(90px, calc(env(safe-area-inset-bottom) + 74px)); width: 170px; height: 150px; pointer-events: auto; }
.mob-btn { position: absolute; width: 62px; height: 62px; border-radius: 50%; border: 1px solid rgba(239,228,205,.35); background: rgba(12,11,9,.55); color: var(--bone); font-size: 22px; display: flex; align-items: center; justify-content: center; backdrop-filter: blur(3px); touch-action: none; }
